import random


class TwentyFourPointGame:
    MAGIC_PASS = 'pass'
    TARGET_VALUE = 24

    def __init__(self) -> None:
        self._nums = []

    def _generate_cards(self):
        for i in range(4):
            self._nums.append(random.randint(1, 9))

    def get_my_cards(self):
        self._nums = []
        self._generate_cards()
        return list(self._nums)

    def _count_numeric_chars(self, expression):
        statistic = {}
        for c in expression:
            if c.isdigit() and int(c) in self._nums:
                statistic[c] = statistic.get(c, 0) + 1
        return statistic

    def _validate_numbers_used(self, expression):
        statistic = self._count_numeric_chars(expression)
        nums_used = statistic.copy()

        for num in self._nums:
            num_str = str(num)
            if nums_used.get(num_str, -100) != -100 and nums_used[num_str] > 0:
                nums_used[num_str] -= 1
            else:
                return False

        return all(count == 0 for count in nums_used.values())

    def answer(self, expression):
        if expression == self.MAGIC_PASS:
            return self.get_my_cards()
        if not self._validate_numbers_used(expression):
            return False
        return self.evaluate_expression(expression)

    def _check_result_equals_target(self, expression):
        try:
            return eval(expression) == self.TARGET_VALUE
        except Exception:
            return False

    def evaluate_expression(self, expression):
        return self._check_result_equals_target(expression)
